function islandsAfterEachFill(m: number, n: number, positions: number[][]): number[] {
  const land = new Uint8Array(m * n);
  const out: number[] = [];
  for (const [r, c] of positions) {
    land[r * n + c] = 1;
    const seen = new Uint8Array(m * n);
    let count = 0;
    for (let s = 0; s < m * n; s++) {
      if (!land[s] || seen[s]) continue;
      count++;
      const stack = [s];
      seen[s] = 1;
      while (stack.length) {
        const x = stack.pop()!, xr = Math.floor(x / n), xc = x % n;
        for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const nr = xr + dr, nc = xc + dc, y = nr * n + nc;
          if (nr >= 0 && nr < m && nc >= 0 && nc < n && land[y] && !seen[y]) { seen[y] = 1; stack.push(y); }
        }
      }
    }
    out.push(count);
  }
  return out;
}

