class Solution:
    def islandsAfterEachFill(self, m: int, n: int, positions: List[List[int]]) -> List[int]:
        land = set()
        out = []
        for r, c in positions:
            land.add((r, c))
            seen = set()
            count = 0
            for cell in land:
                if cell in seen:
                    continue
                count += 1
                seen.add(cell)
                stack = [cell]
                while stack:
                    x, y = stack.pop()
                    for nb in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                        if nb in land and nb not in seen:
                            seen.add(nb)
                            stack.append(nb)
            out.append(count)
        return out

