function islandsAfterEachFill(m: number, n: number, positions: number[][]): number[] {
  const parent = new Int32Array(m * n).fill(-1); // -1 means water
  const size = new Int32Array(m * n);
  const find = (x: number): number => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]]; // path halving
      x = parent[x];
    }
    return x;
  };
  const out: number[] = [];
  let count = 0;
  for (const [r, c] of positions) {
    const id = r * n + c;
    if (parent[id] !== -1) { out.push(count); continue; }
    parent[id] = id;
    size[id] = 1;
    count++;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
      const nb = nr * n + nc;
      if (parent[nb] === -1) continue;
      let a = find(id), b = find(nb);
      if (a === b) continue;
      if (size[a] < size[b]) [a, b] = [b, a];
      parent[b] = a;
      size[a] += size[b];
      count--;
    }
    out.push(count);
  }
  return out;
}

