class Solution:
    def islandsAfterEachFill(self, m: int, n: int, positions: List[List[int]]) -> List[int]:
        parent = [-1] * (m * n)  # -1 means water
        size = [0] * (m * n)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        out = []
        count = 0
        for r, c in positions:
            cell = r * n + c
            if parent[cell] != -1:
                out.append(count)
                continue
            parent[cell] = cell
            size[cell] = 1
            count += 1
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < m and 0 <= nc < n and parent[nr * n + nc] != -1:
                    a, b = find(cell), find(nr * n + nc)
                    if a != b:
                        if size[a] < size[b]:
                            a, b = b, a
                        parent[b] = a
                        size[a] += size[b]
                        count -= 1
            out.append(count)
        return out

